/* ---------------- 网络 ---------------- */
let socket=null,online=false,mySeat=1,roomId=null,netOk=false;
const netBadge=document.getElementById("netBadge");
function netInit(){
  try{
    socket=io({reconnectionAttempts:5});
    socket.on("connect",()=>{netOk=true;netBadge.textContent="●在线";netBadge.classList.add("on");});
    socket.on("disconnect",()=>{netOk=false;netBadge.textContent="●离线";netBadge.classList.remove("on");});
    socket.on("roomUpdate",d=>{if(scr==="room")updateRoomUI(d.count);});
    socket.on("readyState",d=>{if(scr==="room")updateReadyUI(d.readyCount);});
    socket.on("startGame",()=>{startMatch(true);});
    socket.on("peerLeft",()=>{toast("对方已离开房间");if(online){online=false;backToMenu();}});
    socket.on("rematchAsk",()=>{peerAgain=true;tryRematch();});
    socket.on("data",onNetData);
  }catch(e){netOk=false;}
}
function send(o){if(online&&socket&&netOk)socket.emit("data",o);}
