/* ============================================================
   战斗引擎
   ============================================================ */
let fighters=[],fx=[],projs=[],shake=0,flash=0,slowmo=0;
let timer=99,tAcc=0,running=false,roundActive=false,frame=0;
let roundNum=1,wins=[0,0],bestOf=2; // wins to 2
let cine=null; // {t,dur,ci,name,text,kind}
let bann=null;
let stat={dmg:[0,0],maxCombo:[0,0]};
let resShareText="";
let practice=false;

function mkFighter(ci,x,facing,ctrl,seat){
  return {ci,x,y:GROUND,vx:0,vy:0,facing,ctrl,seat, // ctrl: "me"|"ai"|"net"
    hp:100,en:0,onG:true,stun:0,inv:0,blk:false,crh:false,
    atk:0,atkType:null,atkDone:false,
    cdLP:0,cdHP:0,cdLK:0,cdHK:0,cdS1:0,cdS2:0,cdDG:0,
    dashT:0,spinT:0,rushT:0,rushHits:0,stormT:0,stormTick:0,
    combo:0,comboT:0,bubble:"",bubT:0,after:[],
    netX:x,netY:GROUND,dead:false};
}
function startMatch(isOnline){
  online=isOnline&&!!socket&&netOk;practice=!online;
  wins=[0,0];roundNum=1;stat={dmg:[0,0],maxCombo:[0,0]};
  startRound();
  if(innerHeight>innerWidth)document.getElementById("rotateHint").classList.remove("hide");
}
function startRound(){
  const meCi=mySeat-1, opCi=2-mySeat;
  fighters=[];
  const f1=mkFighter(0,VW*0.25,1,null,1);
  const f2=mkFighter(1,VW*0.75,-1,null,2);
  f1.ctrl=(mySeat===1)?"me":(online?"net":"ai");
  f2.ctrl=(mySeat===2)?"me":(online?"net":"ai");
  fighters=[f1,f2];
  fx=[];projs=[];shake=0;flash=0;slowmo=0;cine=null;
  timer=99;tAcc=0;roundActive=false;
  showScr(null);
  const me=myFighter();
  banner("ROUND "+roundNum,1300,"#ffd23a");
  SFX.count();
  setTimeout(()=>{banner("FIGHT!",900,"#ff4d4d");SFX.boom();roundActive=true;
    fighters.forEach(f=>{f.bubble=CHARS[f.ci].intro;f.bubT=1800;});
  },1400);
  startMusic();
  if(!running){running=true;last=performance.now();requestAnimationFrame(loop);}
}
function myFighter(){return fighters[mySeat-1];}
function otherFighter(){return fighters[2-mySeat];}
/* ---------------- 回合与比赛结束 ---------------- */
function roundEnd(winnerSeat,how){
  if(!roundActive)return;roundActive=false;
  wins[winnerSeat-1]++;
  SFX.ko();
  banner(how==="ko"?"K.O. !":"TIME UP!",1400,"#ff4d4d");
  flash=1;slowmo=900;
  setTimeout(()=>{
    if(wins[winnerSeat-1]>=bestOf){matchEnd(winnerSeat);}
    else{roundNum++;startRound();}
  },2000);
}
function matchEnd(winnerSeat){
  running=false;stopMusic();
  const wc=CHARS[winnerSeat-1];
  document.getElementById("resFace").src=wc.face;
  document.getElementById("resTitle").textContent=wc.name+" 获胜！";
  let t=wc.winText+"　台词：「"+wc.winQuote+"」";
  if(practice)t+= (winnerSeat===mySeat)?"　🏆 你赢了！":"　😵 惜败，再战！";
  else t+=(winnerSeat===mySeat)?"　🏆 你赢了！":"　对方技高一筹！";
  document.getElementById("resText").textContent=t;
  document.getElementById("resStats").textContent=
    "比分 "+wins[0]+" : "+wins[1]+"　|　我方总伤害 "+stat.dmg[mySeat-1]+"　最高连击 "+stat.maxCombo[mySeat-1]+" COMBO";
  resShareText="【梅开格斗：开放之战】"+wc.name+"在梅州开放大学·荣耀擂台获胜！比分"+wins[0]+":"+wins[1]+"，最高"+Math.max(stat.maxCombo[0],stat.maxCombo[1])+"连击！来挑战吗？";
  (winnerSeat===mySeat?SFX.win:SFX.lose)();
  setTimeout(()=>showScr("scrRes"),900);
}
/* ---------------- 特效 ---------------- */
function banner(text,dur,color){bann={text,t:dur,color};}
function spark(x,y,color,n){n=n||10;for(let i=0;i<n;i++)fx.push({t:"p",x,y,vx:(Math.random()-0.5)*10,vy:-Math.random()*8,life:420,color});}
function ring(x,y,color,big){fx.push({t:"r",x,y,r:big?14:6,grow:big?0.32:0.18,life:big?500:340,color});}
function dmgText(x,y,v,crit){fx.push({t:"d",x,y,v:"-"+v,life:780,crit});}
function star(x,y,col){fx.push({t:"s",x,y,vx:(Math.random()-0.5)*7,vy:-Math.random()*9-2,rot:Math.random()*6,life:640,col:col||"#ffd23a"});}
function shockwave(x,y,col){ring(x,y,col,true);spark(x,y,col,18);}
/* ---------------- 攻击定义 ---------------- */
const NORMALS={
  LP:{dmg:5, range:62, dur:180,cd:280, snd:"lp"},
  HP:{dmg:9, range:70, dur:260,cd:500, snd:"hp"},
  LK:{dmg:7, range:84, dur:220,cd:380, snd:"lk"},
  HK:{dmg:12,range:96, dur:320,cd:640, snd:"hk", lunge:5}
};
function tryNormal(f,o,type){
  if(f["cd"+type]>0||f.stun>0||f.atk>0||cine)return;
  const m=NORMALS[type];
  f.atkType=type;f.atk=m.dur;f.atkDone=false;f["cd"+type]=m.cd+m.dur;
  if(m.lunge)f.vx=f.facing*m.lunge*1.4;
  SFX[m.snd]();
  netCast(type);
}
function trySkill(f,o,which){
  if(f.stun>0||cine)return;
  const c=CHARS[f.ci];
  if(which==="S1"){
    if(f.cdS1>0)return;f.cdS1=2500;
    SFX.skill();
    const p={owner:f.seat,ci:f.ci,x:f.x+f.facing*36,y:f.y-72,vx:f.facing*10,dmg:9,life:1400,kind:"fist"};
    projs.push(p);netCast("S1");
    f.bubble=c.s1Name+"！";f.bubT=900;
  }
  else if(which==="S2"){
    if(f.cdS2>0)return;f.cdS2=f.ci===0?4000:5200;
    SFX.skill();netCast("S2");
    if(f.ci===0){ // 云端疾步
      f.dashT=300;f.inv=Math.max(f.inv,320);
      f.bubble=c.s2Name+"！";f.bubT=900;
    }else{ // 围龙旋风腿
      f.spinT=620;f.atkDone=false;f.spinHits=0;
      f.bubble=c.s2Name+"！";f.bubT=900;
    }
  }
  else if(which==="SP"){
    if(f.en<50)return;f.en-=50;
    startCine(f,"sp");netCast("SP");
  }
  else if(which==="UL"){
    if(f.en<100)return;f.en=0;
    startCine(f,"ul");netCast("UL");
  }
}
function tryDodge(f){
  if(f.cdDG>0||f.stun>0||cine)return;
  f.cdDG=1200;f.inv=Math.max(f.inv,380);
  f.x+=f.facing*-1*110; // 后撤闪避
  f.x=Math.max(46,Math.min(VW-46,f.x));
  for(let i=0;i<5;i++)f.after.push({x:f.x+ (Math.random()-0.5)*30,y:f.y,life:280});
  SFX.dodge();netCast("DG");
}
/* ---------------- 大招/必杀 运镜 ---------------- */
function startCine(f,kind){
  const c=CHARS[f.ci];
  cine={t:0,dur:kind==="ul"?1250:850,ci:f.ci,seat:f.seat,kind,
    name:kind==="ul"?c.ulName:c.spName};
  SFX.charge();
  setTimeout(()=>{ if(kind==="ul")execUlt(f); else execSuper(f); },kind==="ul"?1250:850);
}
function execSuper(f){
  const c=CHARS[f.ci];
  banner(c.spName,900,c.aura2);
  if(f.ci===0){f.stormT=1200;f.stormTick=0;} // 知识风暴
  else{f.rushT=900;f.rushHits=0;} // 嘉应赤焰破
  SFX.boom();shake=14;
}
function execUlt(f){
  const c=CHARS[f.ci];
  banner(c.ulText,1500,"#ffd23a");
  flash=1;shake=26;slowmo=500;SFX.boom();
  if(f.ci===0){ // 雷霆破：全屏雷柱
    for(let i=0;i<7;i++){
      const lx=80+i*(VW-160)/6;
      setTimeout(()=>{fx.push({t:"bolt",x:lx,life:420});SFX.hit();shockwave(lx,GROUND,"#aee0ff");},i*90);
    }
    setTimeout(()=>ultHitCheck(f,38,"#4da3ff"),420);
  }else{ // 赤焰龙魂：火龙横贯
    fx.push({t:"dragon",x:f.facing>0?-100:VW+100,dir:f.facing,y:GROUND-110,life:1400,ph:0});
    setTimeout(()=>ultHitCheck(f,38,"#ff5a2a"),600);
    SFX.charge();
  }
}
function ultHitCheck(f,dmg,col){
  if(f.ctrl==="net")return; // 远端镜像只演特效，伤害由对方权威发来
  const o=fighters[2-f.seat];
  if(o.inv>0||o.dead)return;
  let final=dmg;
  if(o.blk)final=Math.round(dmg*0.45);
  applyHit(f,o,final,f.facing*13,-10,720,true,col);
  slowmo=700;flash=0.8;
}
/* ---------------- 命中处理 ---------------- */
function applyHit(att,vic,dmg,kx,ky,stun,crit,col){
  if(vic.inv>0||vic.dead)return false;
  if(vic.blk&&!crit){dmg=Math.max(1,Math.round(dmg*0.3));stun=120;kx*=0.3;ky=0;SFX.block();vic.en=Math.min(100,vic.en+2);
    ring(vic.x+vic.facing*-26,vic.y-70,"#7fb8ff");}
  else SFX.hit();
  vic.hp=Math.max(0,vic.hp-dmg);
  vic.stun=Math.max(vic.stun,stun);vic.inv=Math.max(vic.inv,200);
  vic.vx=kx;vic.vy=ky;if(ky)vic.onG=false;
  att.en=Math.min(100,att.en+8);vic.en=Math.min(100,vic.en+5);
  att.combo++;att.comboT=1100;
  stat.dmg[att.seat-1]+=dmg;
  stat.maxCombo[att.seat-1]=Math.max(stat.maxCombo[att.seat-1],att.combo);
  spark(vic.x,vic.y-72,col||"#ff6b4d",crit?20:10);
  ring(vic.x,vic.y-72,crit?"#ffd23a":"#fff");
  dmgText(vic.x,vic.y-150,dmg,crit||att.combo>=5);
  if(crit)for(let i=0;i<7;i++)star(vic.x,vic.y-70,col);
  shake=Math.max(shake,crit?22:8);
  comboShout(att);
  /* 联机：作为攻击方，把命中同步给对方（对方的本体由对方权威，但我们发事件让其扣血） */
  if(online&&att.ctrl==="me")send({k:"hit",dmg,kx,ky,stun,crit:!!crit,col:col||null});
  if(vic.hp<=0&&!vic.dead){vic.dead=true;
    if(!online||vic.ctrl!=="net"){ // 死的是本地权威角色
      if(online)send({k:"dead"});
      roundEnd(att.seat,"ko");
    }
  }
  return true;
}
function comboShout(f){
  const c=f.combo;
  if(c===3)banner("Good!  3 COMBO",600,"#7fffa0");
  else if(c===5)banner("Great!  5 COMBO",600,"#7fd0ff");
  else if(c===7)banner("Excellent!  7 COMBO",650,"#ffb86b");
  else if(c>=10&&c%2===0){banner("SUPER COMBO! "+c,800,"#ffd23a");SFX.cheer();shake=Math.max(shake,16);}
}
/* ---------------- 网络同步 ---------------- */
let stCount=0;
function netCast(move){if(online)send({k:"cast",move});}
function onNetData(d){
  const rf=fighters[2-mySeat]; // 远端角色镜像（对方控制）
  const me=myFighter();
  if(!d||!fighters.length)return;
  if(d.k==="st"&&rf){
    rf.netX=d.x;rf.netY=d.y;rf.vx=d.vx;rf.vy=d.vy;rf.facing=d.f;
    rf.hp=d.hp;rf.en=d.en;rf.blk=d.blk;rf.crh=d.crh;
    if(d.stun)rf.stun=Math.max(rf.stun,80);
  }
  else if(d.k==="cast"&&rf){
    const fake={...rf};
    if(NORMALS[d.move]){rf.atkType=d.move;rf.atk=NORMALS[d.move].dur;rf.atkDone=true;SFX[NORMALS[d.move].snd]();}
    else if(d.move==="S1"){projs.push({owner:rf.seat,ci:rf.ci,x:rf.x+rf.facing*36,y:rf.y-72,vx:rf.facing*10,dmg:9,life:1400,kind:"fist",ghost:true});SFX.skill();}
    else if(d.move==="S2"){if(rf.ci===0){rf.dashT=300;}else{rf.spinT=620;}SFX.skill();}
    else if(d.move==="SP"){startCine(rf,"sp");}
    else if(d.move==="UL"){startCine(rf,"ul");}
    else if(d.move==="DG"){rf.inv=380;SFX.dodge();}
  }
  else if(d.k==="hit"&&me){ // 对方打中了我（对方权威判定）
    applyRemoteHit(me,d);
  }
  else if(d.k==="dead"&&rf){ // 对方阵亡
    rf.dead=true;rf.hp=0;roundEnd(mySeat,"ko");
  }
  else if(d.k==="timeup"){roundEnd(d.w,"time");}
  else if(d.k==="again"){peerAgain=true;tryRematch();}
}
function applyRemoteHit(me,d){
  if(me.inv>0&&!d.crit)return;
  let dmg=d.dmg;
  me.hp=Math.max(0,me.hp-dmg);
  me.stun=Math.max(me.stun,d.stun);me.inv=Math.max(me.inv,200);
  me.vx=d.kx;me.vy=d.ky;if(d.ky)me.onG=false;
  me.en=Math.min(100,me.en+5);
  spark(me.x,me.y-72,d.col||"#ff6b4d",d.crit?20:10);
  dmgText(me.x,me.y-150,dmg,d.crit);
  shake=Math.max(shake,d.crit?22:8);SFX.hit();
  if(me.hp<=0&&!me.dead){me.dead=true;send({k:"dead"});roundEnd(mySeat===1?2:1,"ko");}
}
/* ---------------- AI ---------------- */
function aiUpdate(f,o,dt){
  f.aiT=(f.aiT||0)-dt;
  const dx=o.x-f.x,adx=Math.abs(dx);
  if(f.stun>0||cine)return;
  f.facing=dx>0?1:-1;
  if(f.aiT<=0){
    f.aiT=150+Math.random()*230;
    f.aiMove=adx>120?Math.sign(dx):(Math.random()<0.3?-Math.sign(dx):0);
    f.blk=Math.random()<0.12&&adx<110;
    if(!f.blk){
      if(adx<95&&Math.random()<0.65)tryNormal(f,o,["LP","HP","LK","HK"][Math.floor(Math.random()*4)]);
      if(adx>180&&Math.random()<0.3)trySkill(f,o,"S1");
      if(Math.random()<0.18)trySkill(f,o,"S2");
      if(f.en>=50&&adx<160&&Math.random()<0.3)trySkill(f,o,"SP");
      if(f.en>=100&&Math.random()<0.5)trySkill(f,o,"UL");
      if(Math.random()<0.1&&f.onG){f.vy=-13;f.onG=false;}
      if(Math.random()<0.08)tryDodge(f);
    }
  }
  if(!f.blk)f.vx=(f.aiMove||0)*3.1;else f.vx=0;
}
/* ---------------- 主循环 ---------------- */
let last=0;
function loop(now){
  if(!running)return;
  let dt=Math.min(42,now-last);last=now;frame++;
  if(slowmo>0){slowmo-=dt;dt*=0.35;}
  update(dt);draw();
  requestAnimationFrame(loop);
}
function update(dt){
  if(cine){cine.t+=dt;if(cine.t>=cine.dur)cine=null;return;}
  if(roundActive){
    tAcc+=dt;
    if(tAcc>1000){tAcc-=1000;timer--;
      if(timer<=10&&timer>0)SFX.tick();
      if(timer<=0){
        if(!online||mySeat===1){ // 房主/单机权威
          const w=fighters[0].hp>=fighters[1].hp?1:2;
          if(online)send({k:"timeup",w});
          roundEnd(w,"time");
        }
        return;
      }
    }
  }
  const [f1,f2]=fighters;
  for(const f of fighters){
    const o=f===f1?f2:f1;
    if(f.comboT>0){f.comboT-=dt;if(f.comboT<=0)f.combo=0;}
    if(f.stun>0)f.stun-=dt;
    else if(f.ctrl==="me"&&roundActive){
      f.blk=!!keys.BL&&f.onG;
      f.crh=!!keys.D&&f.onG;
      f.vx=0;
      if(!f.blk&&!f.crh){
        if(keys.L){f.vx=-3.8;f.facing=-1;}
        if(keys.R){f.vx=3.8;f.facing=1;}
        if(keys.U&&f.onG){f.vy=-13.5;f.onG=false;SFX.jump();}
      }
      if(keys.LP)tryNormal(f,o,"LP");
      if(keys.HP)tryNormal(f,o,"HP");
      if(keys.LK)tryNormal(f,o,"LK");
      if(keys.HK)tryNormal(f,o,"HK");
      if(keys.S1)trySkill(f,o,"S1");
      if(keys.S2)trySkill(f,o,"S2");
      if(keys.SP)trySkill(f,o,"SP");
      if(keys.UL)trySkill(f,o,"UL");
      if(keys.DG)tryDodge(f);
    }
    else if(f.ctrl==="ai"&&roundActive)aiUpdate(f,o,dt);
    else if(f.ctrl==="net"){ // 插值到对方汇报的位置
      f.x+= (f.netX-f.x)*0.35;
      f.y+= (f.netY-f.y)*0.35;
    }
    /* 冷却 */
    ["cdLP","cdHP","cdLK","cdHK","cdS1","cdS2","cdDG"].forEach(c=>{if(f[c]>0)f[c]-=dt;});
    if(f.inv>0)f.inv-=dt;
    if(f.bubT>0)f.bubT-=dt;
    /* 普攻命中 */
    if(f.atk>0){f.atk-=dt;
      const m=NORMALS[f.atkType];
      if(m&&!f.atkDone&&f.atk<m.dur*0.55){
        f.atkDone=true;
        if(f.ctrl!=="net"){
          const dx=(o.x-f.x)*f.facing;
          if(dx>-12&&dx<m.range&&Math.abs(o.y-f.y)<96)
            applyHit(f,o,m.dmg+Math.floor(Math.random()*2),f.facing*4,-2,260,false);
        }
      }
    }
    /* 云端疾步 */
    if(f.dashT>0){f.dashT-=dt;f.x+=f.facing*9;
      if(frame%2===0)f.after.push({x:f.x,y:f.y,life:300});}
    /* 围龙旋风腿 */
    if(f.spinT>0){f.spinT-=dt;f.x+=f.facing*3.4;
      if(f.ctrl!=="net"&&f.spinHits<2&&f.spinT<620-(f.spinHits+1)*220){
        const dx=Math.abs(o.x-f.x);
        if(dx<86){applyHit(f,o,6,f.facing*3,-2,220,false,"#ffc23a");}
        f.spinHits++;
      }
      if(frame%3===0)ring(f.x,f.y-60,"#ffc23a");
    }
    /* 知识风暴 */
    if(f.stormT>0){f.stormT-=dt;
      if(frame%2===0){const a=Math.random()*6.28;fx.push({t:"page",x:f.x+Math.cos(a)*100,y:f.y-70+Math.sin(a)*80,vx:Math.cos(a+1.5)*3,vy:Math.sin(a+1.5)*3,life:600});}
      f.stormTick+=dt;
      if(f.ctrl!=="net"&&f.stormTick>360){f.stormTick=0;
        if(Math.abs(o.x-f.x)<150)applyHit(f,o,7,f.facing*2,-1,200,false,"#aee0ff");}
    }
    /* 嘉应赤焰破 */
    if(f.rushT>0){f.rushT-=dt;f.x+=f.facing*7;
      if(frame%2===0)spark(f.x-f.facing*20,f.y-60,"#ff5a2a",2);
      if(f.ctrl!=="net"&&f.rushHits<3&&f.rushT<900-(f.rushHits+1)*240){
        if(Math.abs(o.x-f.x)<90){
          const lastHit=f.rushHits===2;
          applyHit(f,o,lastHit?12:6,f.facing*(lastHit?11:2),lastHit?-9:-1,lastHit?500:200,lastHit,"#ff5a2a");
        }
        f.rushHits++;
      }
    }
    /* 物理 */
    f.x+=f.vx;f.y+=f.vy;
    if(!f.onG)f.vy+=0.72;
    if(f.y>=GROUND){if(!f.onG&&f.vy>6)spark(f.x,GROUND,"#888",5);f.y=GROUND;f.vy=0;f.onG=true;}
    f.x=Math.max(46,Math.min(VW-46,f.x));
    f.after=f.after.filter(a=>(a.life-=dt)>0);
  }
  /* 推开 */
  if(Math.abs(f1.x-f2.x)<44&&f1.ctrl!=="net"&&f2.ctrl!=="net"){const m=f1.x<f2.x?-1:1;f1.x+=m*1.4;f2.x-=m*1.4;}
  /* 弹幕 */
  for(const p of projs){
    p.x+=p.vx;p.life-=dt;
    if(frame%2===0)fx.push({t:"p",x:p.x,y:p.y,vx:-p.vx*0.2,vy:(Math.random()-0.5)*2,life:240,color:p.ci===0?"#7fb8ff":"#ff7a3a"});
    if(!p.ghost){
      const vic=fighters[2-p.owner];
      if(vic&&!vic.dead&&Math.abs(vic.x-p.x)<40&&Math.abs((vic.y-72)-p.y)<70&&vic.inv<=0){
        applyHit(fighters[p.owner-1],vic,p.dmg,Math.sign(p.vx)*6,-3,300,false,p.ci===0?"#4da3ff":"#ff5a2a");
        p.life=0;shockwave(p.x,p.y,p.ci===0?"#7fb8ff":"#ff7a3a");
      }
    }
    if(p.x<-60||p.x>VW+60)p.life=0;
  }
  projs=projs.filter(p=>p.life>0);
  /* fx 衰减 */
  for(const p of fx){p.life-=dt;
    if(p.t==="p"){p.x+=p.vx;p.y+=p.vy;p.vy+=0.3;}
    else if(p.t==="d")p.y-=0.6;
    else if(p.t==="r")p.r+=dt*(p.grow||0.18);
    else if(p.t==="s"){p.x+=p.vx;p.y+=p.vy;p.vy+=0.35;p.rot+=0.2;}
    else if(p.t==="page"){p.x+=p.vx;p.y+=p.vy;}
    else if(p.t==="dragon"){p.x+=p.dir*9;p.ph+=0.25;}
  }
  fx=fx.filter(p=>p.life>0);
  if(bann){bann.t-=dt;if(bann.t<=0)bann=null;}
  if(shake>0)shake*=0.86;
  if(flash>0)flash-=dt/300;
  /* 状态上报 */
  if(online&&roundActive){
    stCount++;
    if(stCount%3===0){const me=myFighter();
      send({k:"st",x:me.x,y:me.y,vx:me.vx,vy:me.vy,f:me.facing,hp:me.hp,en:me.en,blk:me.blk,crh:me.crh,stun:me.stun>0?1:0});}
  }
  updateBtnUI();
}
/* ---------------- 按钮冷却 UI ---------------- */
function cdRing(el,pct){
  if(!el)return;const cd=el.querySelector(".cd");if(!cd)return;
  if(pct<=0){cd.style.background="none";return;}
  cd.style.background="conic-gradient(rgba(0,0,0,.65) "+(pct*360)+"deg, transparent 0deg)";
}
function updateBtnUI(){
  const me=myFighter();if(!me)return;
  cdRing(document.getElementById("bS1"),me.cdS1/2500);
  cdRing(document.getElementById("bS2"),me.cdS2/(me.ci===0?4000:5200));
  const sp=document.getElementById("bSP"),ul=document.getElementById("bUL");
  sp.classList.toggle("ready",me.en>=50);sp.classList.toggle("dis",me.en<50);
  ul.classList.toggle("ready",me.en>=100);ul.classList.toggle("dis",me.en<100);
}
/* ============================================================
   绘制
   ============================================================ */
function draw(){
  ctx.save();
  if(shake>1)ctx.translate((Math.random()-0.5)*shake,(Math.random()-0.5)*shake);
  drawBG();
  drawCrowd();
  for(const p of projs)drawProj(p);
  const order=[...fighters].sort((a,b)=>a.y-b.y);
  order.forEach(drawFighter);
  drawFx();
  drawHUD();
  if(cine)drawCine();
  if(bann){ctx.font="bold "+(bann.text.length>8?32:50)+"px 'STKaiti','KaiTi','Microsoft YaHei'";
    ctx.fillStyle=bann.color;ctx.textAlign="center";ctx.shadowColor="rgba(0,0,0,.8)";ctx.shadowBlur=16;
    ctx.fillText(bann.text,VW/2,VH/2-36);ctx.shadowBlur=0;}
  if(flash>0){ctx.fillStyle="rgba(255,255,255,"+Math.min(1,flash)+")";ctx.fillRect(0,0,VW,VH);}
  ctx.restore();
}
function drawBG(){
  const t=frame/60;
  /* 夜空 */
  const g=ctx.createLinearGradient(0,0,0,VH);
  g.addColorStop(0,"#0a0d2e");g.addColorStop(.5,"#1a1545");g.addColorStop(.85,"#3a1f4e");g.addColorStop(1,"#241430");
  ctx.fillStyle=g;ctx.fillRect(0,0,VW,VH);
  /* 星 + 月 */
  ctx.fillStyle="rgba(255,255,255,.8)";
  for(let i=0;i<24;i++){const sx=(i*173)%VW,sy=(i*97)%160;ctx.globalAlpha=0.3+0.5*Math.abs(Math.sin(t*2+i));ctx.fillRect(sx,sy,2,2);}
  ctx.globalAlpha=1;
  /* 远景城市剪影 */
  ctx.fillStyle="#141233";
  for(let i=0;i<12;i++){const bx=i*84,bh=60+((i*53)%90);ctx.fillRect(bx,200-bh+60,60,bh+40);}
  ctx.fillStyle="#ffd23a";
  for(let i=0;i<40;i++){const wx=20+(i*47)%(VW-40),wy=160+(i*31)%110;if((i+Math.floor(t))%4)ctx.fillRect(wx,wy,3,3);}
  /* 中景：教学楼 + 发光校名 + 智慧大屏 */
  ctx.fillStyle="#222a4e";ctx.fillRect(40,150,330,GROUND-150);
  ctx.fillStyle="#2e3a66";for(let fy=170;fy<GROUND-26;fy+=40)for(let fxx=58;fxx<350;fxx+=46)ctx.fillRect(fxx,fy,30,24);
  /* 发光校名 */
  ctx.save();ctx.shadowColor="#ffb02e";ctx.shadowBlur=18;
  ctx.fillStyle="#ffd23a";ctx.font="bold 26px 'STKaiti','KaiTi',serif";ctx.textAlign="center";
  ctx.fillText("梅 州 开 放 大 学",205,140);ctx.restore();
  /* 智慧教育大屏 */
  ctx.fillStyle="#06122a";ctx.fillRect(VW-330,120,280,150);
  ctx.strokeStyle="#3d8bff";ctx.lineWidth=3;ctx.strokeRect(VW-330,120,280,150);
  ctx.save();ctx.beginPath();ctx.rect(VW-328,122,276,146);ctx.clip();
  ctx.fillStyle="rgba(61,139,255,.18)";
  for(let i=0;i<6;i++)ctx.fillRect(VW-328,122+((t*30+i*26)%150),276,3);
  ctx.fillStyle="#7fb8ff";ctx.font="bold 22px 'Microsoft YaHei'";ctx.textAlign="center";
  const msgs=["荣耀擂台","智慧教育","终身学习","开放之战"];
  ctx.fillText(msgs[Math.floor(t/2)%msgs.length],VW-190,180);
  ctx.font="12px 'Microsoft YaHei'";ctx.fillStyle="#4d7fc0";
  ctx.fillText("MEIZHOU OPEN UNIVERSITY FIGHTERS",VW-190,210);
  ctx.restore();
  /* 围龙屋纹样横幅 */
  ctx.strokeStyle="rgba(255,170,60,.5)";ctx.lineWidth=2;
  for(let i=0;i<5;i++){ctx.beginPath();ctx.arc(430+i*26,GROUND-118,12,Math.PI,0);ctx.stroke();}
  /* 灯笼 */
  for(let i=0;i<3;i++){const lx=420+i*60,ly=92+Math.sin(t*1.4+i)*5;
    ctx.strokeStyle="#664";ctx.beginPath();ctx.moveTo(lx,60);ctx.lineTo(lx,ly-14);ctx.stroke();
    ctx.fillStyle="#e03a2a";ctx.beginPath();ctx.ellipse(lx,ly,11,14,0,0,7);ctx.fill();
    ctx.fillStyle="#ffd23a";ctx.fillRect(lx-5,ly+12,10,5);}
  /* 扫动聚光灯 */
  ctx.save();ctx.globalAlpha=0.1;ctx.fillStyle="#9fd4ff";
  const sw=Math.sin(t*0.8)*200;
  ctx.beginPath();ctx.moveTo(VW/2+sw,0);ctx.lineTo(VW/2+sw-160,GROUND);ctx.lineTo(VW/2+sw+160,GROUND);ctx.fill();
  ctx.globalAlpha=0.08;ctx.fillStyle="#ff9d7a";
  ctx.beginPath();ctx.moveTo(VW/2-sw,0);ctx.lineTo(VW/2-sw-160,GROUND);ctx.lineTo(VW/2-sw+160,GROUND);ctx.fill();
  ctx.restore();
  /* 漂浮能量粒子 */
  for(let i=0;i<10;i++){const px=(i*131+t*22)%VW,py=GROUND-40-((i*67)%200)-Math.sin(t+i)*10;
    ctx.fillStyle=i%2?"rgba(77,163,255,.5)":"rgba(255,122,58,.5)";ctx.fillRect(px,py,3,3);}
  /* 擂台地面 */
  ctx.fillStyle="#2c2438";ctx.fillRect(0,GROUND,VW,VH-GROUND);
  const mg=ctx.createLinearGradient(0,GROUND,0,GROUND+16);
  mg.addColorStop(0,"#8c2620");mg.addColorStop(1,"#5a1610");
  ctx.fillStyle=mg;ctx.fillRect(VW*0.1,GROUND,VW*0.8,16);
  ctx.fillStyle="#ffd23a";ctx.font="bold 13px 'Microsoft YaHei'";ctx.textAlign="center";
  ctx.fillText("梅州开放大学 · 荣耀擂台",VW/2,GROUND+38);
  ctx.strokeStyle="rgba(255,210,58,.6)";ctx.lineWidth=2;ctx.strokeRect(VW*0.1,GROUND+24,VW*0.8,22);
}
let crowdArr=null;
function drawCrowd(){
  const t=frame/60;
  if(!crowdArr){crowdArr=[];for(let i=0;i<26;i++)crowdArr.push({x:30+i*36+Math.random()*10,c:["#3a4a7e","#5e3a6e","#3a6e5a","#6e3a3a"][i%4],ph:Math.random()*6});}
  for(const c of crowdArr){
    const b=Math.abs(Math.sin(t*3+c.ph))*6;
    ctx.fillStyle=c.c;
    ctx.beginPath();ctx.arc(c.x,GROUND-118-b,8,0,7);ctx.fill();
    ctx.fillRect(c.x-8,GROUND-112-b,16,18);
  }
}
function drawProj(p){
  ctx.save();ctx.translate(p.x,p.y);
  const col=p.ci===0?"#4da3ff":"#ff5a2a",col2=p.ci===0?"#aee0ff":"#ffc23a";
  ctx.shadowColor=col;ctx.shadowBlur=16;
  ctx.fillStyle=col;ctx.beginPath();ctx.ellipse(0,0,22,12,0,0,7);ctx.fill();
  ctx.fillStyle=col2;ctx.beginPath();ctx.ellipse(-4,0,12,7,0,0,7);ctx.fill();
  if(p.ci===0){ctx.strokeStyle="#fff";ctx.lineWidth=2;
    ctx.beginPath();ctx.moveTo(-18,-4);ctx.lineTo(-8,2);ctx.lineTo(-14,6);ctx.stroke();}
  ctx.restore();
}
function drawFighter(f){
  const c=CHARS[f.ci],x=f.x,y=f.y,fc=f.facing,t=performance.now()/1000;
  /* 残影 */
  for(const a of f.after){ctx.fillStyle=c.aura;ctx.globalAlpha=Math.max(0,a.life/300)*0.4;
    ctx.beginPath();ctx.ellipse(a.x,a.y-60,16,46,0,0,7);ctx.fill();}
  ctx.globalAlpha=1;
  /* 影子 */
  ctx.fillStyle="rgba(0,0,0,.35)";ctx.beginPath();ctx.ellipse(x,GROUND+2,30,8,0,0,7);ctx.fill();
  const walk=(Math.abs(f.vx)>0.5&&f.onG)?Math.sin(t*14)*8:0;
  const atkP=f.atk>0,crouch=f.crh?16:0;
  ctx.save();ctx.translate(x,y-0+crouch*0);ctx.scale(fc,1);
  if(f.stun>0)ctx.rotate(Math.sin(t*40)*0.06);
  if(f.inv>0&&Math.floor(t*20)%2===0)ctx.globalAlpha=0.55;
  if(f.spinT>0)ctx.rotate(Math.sin(t*30)*0.3);
  /* 腿 */
  ctx.strokeStyle=c.pants;ctx.lineWidth=13;ctx.lineCap="round";
  const kick=(atkP&&(f.atkType==="LK"||f.atkType==="HK"))?-(f.atkType==="HK"?50:38):0;
  ctx.beginPath();ctx.moveTo(-6,-52+crouch);ctx.lineTo(-12-walk*0.6,-4);ctx.stroke();
  ctx.beginPath();ctx.moveTo(6,-52+crouch);ctx.lineTo(14+walk*0.6+(kick?34:0),-4+(kick||0));ctx.stroke();
  ctx.fillStyle=c.shoes;
  ctx.beginPath();ctx.ellipse(-14-walk*0.6,-2,13,7,0,0,7);ctx.fill();
  ctx.beginPath();ctx.ellipse(16+walk*0.6+(kick?38:0),-2+(kick||0),13,7,kick?-0.5:0,0,7);ctx.fill();
  /* 身体 */
  ctx.fillStyle=c.jacket;ctx.beginPath();ctx.roundRect(-20,-108+crouch,40,60-crouch*0.5,10);ctx.fill();
  ctx.fillStyle=c.shirt;ctx.fillRect(-7,-104+crouch,14,42-crouch*0.5);
  /* 防御盾 */
  if(f.blk){ctx.strokeStyle=c.aura2;ctx.lineWidth=5;ctx.globalAlpha=0.8;
    ctx.beginPath();ctx.arc(26,-72,34,-1.2,1.2);ctx.stroke();ctx.globalAlpha=1;}
  /* 手臂 */
  ctx.strokeStyle=c.jacket;ctx.lineWidth=12;
  const punch=(atkP&&(f.atkType==="LP"||f.atkType==="HP"))?(f.atkType==="HP"?46:36):0;
  ctx.beginPath();ctx.moveTo(-14,-96+crouch);ctx.lineTo(-24+walk*0.4,-58);ctx.stroke();
  ctx.beginPath();ctx.moveTo(14,-96+crouch);ctx.lineTo(20+punch,-74-(punch?14:0));ctx.stroke();
  ctx.fillStyle="#f2c9a4";
  ctx.beginPath();ctx.arc(20+punch,-74-(punch?14:0),8,0,7);ctx.fill();
  ctx.beginPath();ctx.arc(-24+walk*0.4,-58,8,0,7);ctx.fill();
  if(punch===46||f.rushT>0){ctx.fillStyle=c.aura;ctx.globalAlpha=0.6;
    ctx.beginPath();ctx.arc(20+punch,-88,15,0,7);ctx.fill();ctx.globalAlpha=1;}
  /* 头像 */
  ctx.scale(fc,1);
  ctx.save();ctx.beginPath();ctx.arc(0,-134+crouch,26,0,7);ctx.closePath();ctx.clip();
  ctx.drawImage(c.img,-26,-160+crouch,52,52);ctx.restore();
  ctx.lineWidth=3.5;ctx.strokeStyle=f.seat===1?"#4da3ff":"#ff5a3a";
  ctx.beginPath();ctx.arc(0,-134+crouch,26,0,7);ctx.stroke();
  ctx.scale(fc,1);
  /* 能量光环 */
  if(f.en>=100){ctx.strokeStyle=c.aura;ctx.globalAlpha=0.5+0.4*Math.sin(t*8);ctx.lineWidth=4;
    ctx.beginPath();ctx.arc(0,-88,54,0,7);ctx.stroke();ctx.globalAlpha=1;
    for(let i=0;i<4;i++){const an=t*4+i*1.6;ctx.fillStyle=c.aura2;
      ctx.beginPath();ctx.arc(Math.cos(an)*54,-88+Math.sin(an)*54,3,0,7);ctx.fill();}}
  else if(f.en>=50){ctx.strokeStyle=c.aura;ctx.globalAlpha=0.25;ctx.lineWidth=3;
    ctx.beginPath();ctx.arc(0,-88,48,0,7);ctx.stroke();ctx.globalAlpha=1;}
  ctx.restore();
  /* 头顶名字 */
  ctx.font="bold 14px 'Microsoft YaHei'";ctx.textAlign="center";
  ctx.fillStyle="rgba(0,0,0,.6)";ctx.fillText(c.name,x+1,y-176+crouch+1);
  ctx.fillStyle=f.seat===1?"#9fd4ff":"#ffb09a";ctx.fillText(c.name,x,y-176+crouch);
  /* 台词气泡 */
  if(f.bubT>0){ctx.font="bold 13px 'Microsoft YaHei'";const tw=ctx.measureText(f.bubble).width+18;
    ctx.fillStyle="rgba(255,255,255,.95)";ctx.beginPath();ctx.roundRect(x-tw/2,y-226,tw,26,13);ctx.fill();
    ctx.fillStyle="#c0392b";ctx.fillText(f.bubble,x,y-208);}
}
function drawFx(){
  for(const p of fx){
    if(p.t==="p"){ctx.fillStyle=p.color;ctx.globalAlpha=Math.max(0,p.life/420);
      ctx.beginPath();ctx.arc(p.x,p.y,4,0,7);ctx.fill();ctx.globalAlpha=1;}
    else if(p.t==="r"){ctx.strokeStyle=p.color;ctx.globalAlpha=Math.max(0,p.life/(p.grow?500:340));ctx.lineWidth=3;
      ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.stroke();ctx.globalAlpha=1;}
    else if(p.t==="d"){ctx.font=(p.crit?"bold 30px":"bold 18px")+" 'Microsoft YaHei'";
      ctx.fillStyle=p.crit?"#ffd23a":"#ff5a3a";ctx.textAlign="center";
      ctx.globalAlpha=Math.max(0,p.life/780);ctx.fillText(p.v,p.x,p.y);ctx.globalAlpha=1;}
    else if(p.t==="s"){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);
      ctx.globalAlpha=Math.max(0,p.life/640);ctx.fillStyle=p.col;drawStar(0,0,5,7,3);ctx.restore();ctx.globalAlpha=1;}
    else if(p.t==="page"){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.life/100);
      ctx.fillStyle="rgba(174,224,255,.9)";ctx.fillRect(-6,-8,12,16);
      ctx.strokeStyle="#4da3ff";ctx.strokeRect(-6,-8,12,16);ctx.restore();}
    else if(p.t==="bolt"){ctx.save();ctx.globalAlpha=Math.max(0,p.life/420);
      ctx.strokeStyle="#aee0ff";ctx.lineWidth=6;ctx.shadowColor="#4da3ff";ctx.shadowBlur=22;
      ctx.beginPath();let bx=p.x;ctx.moveTo(bx,0);
      for(let yy=40;yy<=GROUND;yy+=40){bx+=(Math.random()-0.5)*26;ctx.lineTo(bx,yy);}
      ctx.stroke();ctx.restore();}
    else if(p.t==="dragon"){ctx.save();ctx.shadowColor="#ff5a2a";ctx.shadowBlur=26;
      for(let i=0;i<8;i++){const dx=p.x-p.dir*i*34,dy=p.y+Math.sin(p.ph-i*0.6)*26;
        ctx.fillStyle=i===0?"#ffd23a":"rgba(255,"+(120-i*10)+",40,"+(1-i*0.1)+")";
        ctx.beginPath();ctx.arc(dx,dy,26-i*2,0,7);ctx.fill();}
      /* 龙眼 */
      ctx.fillStyle="#fff";ctx.beginPath();ctx.arc(p.x+p.dir*8,p.y-8,4,0,7);ctx.fill();
      ctx.restore();}
  }
}
function drawStar(cx,cy,sp,outer,inner){ctx.beginPath();
  for(let i=0;i<sp*2;i++){const r=i%2?inner:outer,a=i*Math.PI/sp-Math.PI/2;
    ctx.lineTo(cx+Math.cos(a)*r,cy+Math.sin(a)*r);}ctx.closePath();ctx.fill();}
/* 顶部 HUD */
function drawHUD(){
  const [a,b]=fighters,bw=VW*0.34;
  function bar(f,x,flip){
    const c=CHARS[f.ci];
    ctx.fillStyle="rgba(0,0,0,.5)";ctx.beginPath();ctx.roundRect(x,16,bw,18,6);ctx.fill();
    const w=bw*f.hp/100;
    const hg=ctx.createLinearGradient(0,16,0,34);
    if(f.hp>40){hg.addColorStop(0,"#7dff9a");hg.addColorStop(1,"#2aa84a");}
    else if(f.hp>18){hg.addColorStop(0,"#ffd56b");hg.addColorStop(1,"#d58a12");}
    else{hg.addColorStop(0,"#ff8a7a");hg.addColorStop(1,"#c0291a");}
    ctx.fillStyle=hg;
    if(w>0){ctx.beginPath();ctx.roundRect(flip?x+bw-w:x,16,w,18,6);ctx.fill();}
    ctx.strokeStyle="#fff";ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(x,16,bw,18,6);ctx.stroke();
    /* 能量 */
    ctx.fillStyle="rgba(0,0,0,.5)";ctx.fillRect(x,38,bw*0.72,7);
    ctx.fillStyle=f.en>=100?"#ffd23a":(f.en>=50?"#c08aff":"#7a5acd");
    ctx.fillRect(flip?x+bw*0.72-bw*0.72*f.en/100:x,38,bw*0.72*f.en/100,7);
    /* 头像 */
    const ax=flip?x+bw+30:x-30;
    ctx.save();ctx.beginPath();ctx.arc(ax,32,24,0,7);ctx.clip();
    ctx.drawImage(c.img,ax-24,8,48,48);ctx.restore();
    ctx.strokeStyle=f.seat===1?"#4da3ff":"#ff5a3a";ctx.lineWidth=3;
    ctx.beginPath();ctx.arc(ax,32,24,0,7);ctx.stroke();
    /* 名字 + 连击 */
    ctx.fillStyle="#fff";ctx.font="bold 13px 'Microsoft YaHei'";ctx.textAlign=flip?"right":"left";
    ctx.shadowColor="rgba(0,0,0,.7)";ctx.shadowBlur=4;
    ctx.fillText(c.name,flip?x+bw:x,60);ctx.shadowBlur=0;
    if(f.combo>=2){ctx.fillStyle="#ffd23a";ctx.font="bold 20px 'Microsoft YaHei'";
      ctx.fillText(f.combo+" COMBO",flip?x+bw:x,84);}
    /* 局点 */
    for(let i=0;i<2;i++){
      ctx.beginPath();ctx.arc((flip?x+bw-12-i*20:x+12+i*20),50,6,0,7);
      ctx.fillStyle=wins[f.seat-1]>i?"#ffd23a":"rgba(255,255,255,.25)";ctx.fill();}
  }
  bar(a,46,false);bar(b,VW-46-bw,true);
  /* 计时器 */
  ctx.fillStyle="rgba(0,0,0,.6)";ctx.beginPath();ctx.roundRect(VW/2-32,10,64,38,9);ctx.fill();
  ctx.strokeStyle="#ffd23a";ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(VW/2-32,10,64,38,9);ctx.stroke();
  ctx.fillStyle=timer<=10?"#ff4d4d":"#ffd23a";ctx.font="bold 27px 'Microsoft YaHei'";ctx.textAlign="center";
  ctx.fillText(timer,VW/2,39);
}
/* 大招运镜 */
function drawCine(){
  const c=CHARS[cine.ci],pr=cine.t/cine.dur;
  ctx.fillStyle="rgba(5,3,18,"+Math.min(0.86,pr*2)+")";ctx.fillRect(0,0,VW,VH);
  /* 速度线 */
  ctx.strokeStyle=c.aura;ctx.globalAlpha=0.5;
  for(let i=0;i<14;i++){const an=i/14*6.28+pr*3;
    ctx.lineWidth=2+Math.random()*2;
    ctx.beginPath();ctx.moveTo(VW/2+Math.cos(an)*150,VH/2+Math.sin(an)*100);
    ctx.lineTo(VW/2+Math.cos(an)*520,VH/2+Math.sin(an)*360);ctx.stroke();}
  ctx.globalAlpha=1;
  /* 角色特写：从一侧滑入 */
  const slide=Math.min(1,pr*2.6),side=cine.seat===1?-1:1;
  const fx0=VW/2+side*(1-slide)*420 - side*180;
  ctx.save();ctx.shadowColor=c.aura;ctx.shadowBlur=40;
  ctx.beginPath();ctx.arc(fx0,VH/2-26,96,0,7);ctx.clip();
  ctx.drawImage(c.img,fx0-96,VH/2-122,192,192);ctx.restore();
  ctx.lineWidth=6;ctx.strokeStyle=c.aura2;
  ctx.beginPath();ctx.arc(fx0,VH/2-26,96,0,7);ctx.stroke();
  /* 技能名大字 */
  ctx.font="bold "+(cine.kind==="ul"?44:38)+"px 'STKaiti','KaiTi','Microsoft YaHei'";
  ctx.textAlign="center";ctx.fillStyle=c.aura2;
  ctx.shadowColor=c.aura;ctx.shadowBlur=24;
  ctx.fillText(cine.name,VW/2,VH/2+118);
  ctx.shadowBlur=0;
  /* 校园剪影能量纹 */
  ctx.strokeStyle="rgba(255,210,58,"+(0.3+0.3*Math.sin(pr*12))+")";ctx.lineWidth=2;
  ctx.strokeRect(VW/2-200,VH/2+140,400,26);
  ctx.font="13px 'Microsoft YaHei'";ctx.fillStyle="#ffd23a";
  ctx.fillText("梅 州 开 放 大 学 · 荣 耀 擂 台",VW/2,VH/2+158);
}
/* 空闲背景动画（菜单后面） */
function idleLoop(){
  if(!running){frame++;ctx.save();drawBG();drawCrowd();ctx.restore();}
  requestAnimationFrame(idleLoop);
}
setTimeout(idleLoop,100);
